-- Diagnostic-only options for medical services.
-- Each option belongs to one DIAGNOSTIC medical service.
-- Selection is optional and can be SINGLE or MULTIPLE.
CREATE TABLE medical_service_options (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    service_id BIGINT NOT NULL REFERENCES medical_services(id) ON DELETE CASCADE,
    name VARCHAR(200) NOT NULL CHECK (LENGTH(BTRIM(name)) > 0),
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT uq_medical_service_options_service_id_id UNIQUE (service_id, id)
);
CREATE UNIQUE INDEX uq_medical_service_options_name_per_service
    ON medical_service_options (service_id, LOWER(BTRIM(name)));

CREATE TABLE medical_event_options (
    medical_event_id BIGINT NOT NULL REFERENCES medical_events(id) ON DELETE CASCADE,
    service_id BIGINT NOT NULL,
    option_id BIGINT NOT NULL,
    PRIMARY KEY (medical_event_id, option_id),
    FOREIGN KEY (service_id, option_id)
        REFERENCES medical_service_options(service_id, id) ON DELETE RESTRICT
);
CREATE INDEX idx_medical_event_options_option ON medical_event_options(option_id);

-- Enforce that an event uses options of its own service and that the service is DIAGNOSTIC.
CREATE OR REPLACE FUNCTION validate_diagnostic_event_option() RETURNS trigger AS $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM medical_events e
        JOIN medical_services s ON s.id = e.service_id
        WHERE e.id = NEW.medical_event_id
          AND e.service_id = NEW.service_id
          AND s.category = 'DIAGNOSTIC'
    ) THEN
        RAISE EXCEPTION
    'Option must belong to the DIAGNOSTIC service of the medical event';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_validate_diagnostic_event_option
    BEFORE INSERT OR UPDATE ON medical_event_options
    FOR EACH ROW EXECUTE FUNCTION validate_diagnostic_event_option();

-- Endoscopy allows a single option per medical event.
UPDATE medical_services
SET option_selection_mode = 'SINGLE'
WHERE name = 'Endoscopia'
  AND category = 'DIAGNOSTIC'
  AND user_id IS NULL;

